"            // Check how many active allocated contacts this agent currently has
            var activeAllocationsCount = await db.CrmAgentContacts
                .CountAsync(ac => ac.AgentUsername == callerUserId && ac.DeallocatedAt == null, ct);

            if (activeAllocationsCount < contactsLimit)
            {
                int needed = contactsLimit - activeAllocationsCount;

                // Find active contacts that are not currently allocated to any agent
                var unassigned = await db.CrmContacts
                    .Where(c => c.IsActive && !db.CrmAgentContacts.Any(ac => ac.ContactId == c.Id && ac.DeallocatedAt == null))
                    .OrderBy(c => c.FullName)
                    .Take(needed)
                    .ToListAsync(ct);

                if (unassigned.Count > 0)
                {
                    foreach (var contact in unassigned)
                    {
                        var allocation = new CrmAgentContact
                        {
                            Id = Guid.NewGuid(),
                            AgentUsername = callerUserId,
                            ContactId = contact.Id,
                            AllocatedAt = DateTime.UtcNow,
                            CallCount = 0
                        };
                        db.CrmAgentContacts.Add(allocation);
                    }

                    await db.SaveChangesAsync(ct);
                    return new MutationResult { Success = true, Message = $"Successfully allocated {unassigned.Count} new contacts." };
                }
            }

            return new MutationResult { Success = true, Message = "No contacts allocated or already at limit." };
        }
        catch (Exception ex)
        {
            return new MutationResult { Success = false, Message = ex.InnerException?.Message ?? ex.Message };
